// ── Configuration ────────────────────────────────────────────────────────
const ALLOWED_CHATS = [
  '120363223934343497@g.us',   // NaaF group
];

// ── Parse WAHA webhook payload ────────────────────────────────────────────
const body = $input.first().json.body;
const payload = body.payload || {};

// Always ignore messages sent by the bot itself (avoids feedback loops)
if (payload.fromMe) return [];

// ── Find the group/chat JID robustly ─────────────────────────────────────
// Real WAHA group messages: from = sender JID, to = group JID
// Some WEBJS builds set from = group JID — check both.
const rawFrom = payload.from || '';
const rawTo   = payload.to   || '';
const chatId  = rawFrom.endsWith('@g.us') ? rawFrom
              : rawTo.endsWith('@g.us')   ? rawTo
              : rawFrom;

if (!chatId || !ALLOWED_CHATS.includes(chatId)) return [];

// userId = the individual human sender's JID (used as session key)
// Normalise: multi-device WhatsApp can use @lid instead of @c.us for same user
const userId = rawFrom.replace(/@lid$/, '@c.us');

// ── Extract message ID (used for reply-quoting) ───────────────────────────
const rawId   = payload.id;
const messageId = typeof rawId === 'string' ? rawId
                : (rawId?._serialized || rawId?.id || '');

const text = (payload.body || '').trim();

// ── Detect intent ─────────────────────────────────────────────────────────
const result = detectIntent(text);
if (!result) return [];

return [{ json: { ...result, chatId, userId, messageId } }];

// ─────────────────────────────────────────────────────────────────────────
function detectIntent(t) {
  const lower = t.toLowerCase().trim();

  // "Yes / Show more" — must be the *entire* message (short affirmative)
  if (/^(yes|yeah|yep|sure|ok|okay|show more|more|next|more results|yes please|please|go ahead|continue|show|haan|ha|haa|aur dikhao|more dikhao)[\s.!?]*$/.test(lower)) {
    return { intent: 'more' };
  }

  // "No / Stop" — must be the *entire* message (short negative)
  if (/^(no|nope|nah|stop|that'?s (fine|ok|okay|all|enough)|no thanks|no need|i'?m good|done|enough|bas|nahi|na|thats all|that is all)[\s.!?]*$/.test(lower)) {
    return { intent: 'stop' };
  }

  // New search query — extract keyword
  const keyword = detectKeyword(lower);
  if (keyword) return { intent: 'search', keyword };

  return null;
}

function detectKeyword(t) {
  const patterns = [
    /looking for (.+)/i,
    /searching for (.+)/i,
    /search for (.+)/i,
    /look for (.+)/i,
    /find (?:me |a |an )?(.+)/i,
    /need (.+)/i,
    /want (.+)/i,
    /anyone (?:have|has|know|selling|recommend) (.+)/i,
    /know any (.+)/i,
    /any (.+) available/i,
    /any good (.+)/i,
    /where (?:can i|do i) (?:get|find|buy) (.+)/i,
    /(?:can you |please )?(?:help me |tell me )?(?:find|get|locate) (?:a |an )?(.+)/i,
    /recommend (.+)/i,
    /suggest (.+)/i,
    /good (.+) (?:nearby|near me|in \w+)/i,
    /(.+) chahiye/i,
    /(.+) koi hai/i,
    /dhundh raha (?:hoon|hai) (.+)/i,
    /mujhe (.+) chahiye/i,
    /koi accha (.+)/i,
    /best (.+) near/i,
    /best (.+) in/i,
  ];
  const cleaned = (t || '').toLowerCase().trim();
  for (const p of patterns) {
    const m = cleaned.match(p);
    if (m) return m[1].trim().replace(/[?.!,]+$/, '').trim();
  }
  return null;
}

// ── Configuration ────────────────────────────────────────────────────────
const APP_BASE_URL = 'http://localhost:5173';

const result    = $input.first().json;
const filterOut = $('Filter & Detect Intent').first().json;

const webhookPayload = $('WAHA Webhook').first().json.body?.payload || {};
const rawFrom = webhookPayload.from || '';
const rawTo   = webhookPayload.to   || '';

// Group JID (same logic as Filter node; fromMe already blocked there)
const chatId = rawFrom.endsWith('@g.us') ? rawFrom
             : rawTo.endsWith('@g.us')   ? rawTo
             : rawFrom;

const messageId = filterOut.messageId || '';

// ── Build reply text ──────────────────────────────────────────────────────
let text;

if (result.stopped) {
  // User said "No" — session was deleted
  text = 'Got it! Let me know if you need help finding anything else. \uD83D\uDC4D';

} else if (result.error === 'session_expired') {
  // No reply within 15 seconds — session auto-cleared
  text = 'Session timed out \u23F1\uFE0F\nPlease send your search again to start fresh!';

} else if (result.error === 'no_session') {
  // User sent Yes without a prior search (no session found at all)
  text = 'I lost track of your previous search \uD83D\uDE10\nPlease re-send what you were looking for and I\'ll show you more results!';

} else {
  const listings = result.listings || [];
  const keyword  = result.query || filterOut.keyword || '';
  const isMore   = filterOut.intent === 'more';

  if (listings.length === 0) {
    text = 'Sorry, no' + (isMore ? ' more' : '') + ' results found for *\u201C' + keyword + '\u201D*.'
         + (isMore ? '' : '\n\nPost your business at: ' + APP_BASE_URL);

  } else {
    const header = '\uD83D\uDD0D ' + (isMore ? 'More results' : 'Results') + ' for *\u201C' + keyword + '\u201D*:';

    const lines = listings.map(function(l, i) {
      const profile = l.profiles || {};
      const price   = l.price > 0
        ? '\u20B9' + Number(l.price).toLocaleString('en-IN')
        : 'Contact for price';
      const city  = profile.city  ? '\uD83D\uDCCD ' + profile.city  : '';
      const phone = profile.phone ? '\uD83D\uDCDE ' + profile.phone : '';

      const isDb   = l._source === 'db';
      const hasMaps = !!l._mapsUrl;
      let link;
      if (isDb && hasMaps) {
        link = '\uD83D\uDD17 ' + APP_BASE_URL + '/listings/' + l.id
             + '\n   \uD83D\uDDFA\uFE0F ' + l._mapsUrl;
      } else if (isDb) {
        link = '\uD83D\uDD17 ' + APP_BASE_URL + '/listings/' + l.id;
      } else {
        link = '\uD83D\uDDFA\uFE0F ' + l._mapsUrl;
      }

      const details = [city, phone].filter(Boolean).join('  ');
      return (i + 1) + '. *' + l.title + '* \u2014 ' + price
           + '\n   ' + details
           + '\n   ' + link;
    });

    const footer = result.hasMore
      ? '\n\n\uD83D\uDCAC *Do you want more recommendations?* Reply *Yes* or *No*.'
      : '\n\n\u2705 Those are all the recommendations I have!';

    text = header + '\n\n' + lines.join('\n\n') + footer;
  }
}

return [{ json: { chatId, text, messageId } }];
